import pandas as pd
import numpy as np

train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).values
y = train['target'].values

class DecisionTreeClassifier:
    def __init__(self, max_depth=None):
        self.max_depth = max_depth

    def fit(self, X, y):
        self.tree = self._grow(X, y, 0)

    def _grow(self, X, y, depth):
        if depth == self.max_depth or len(np.unique(y)) == 1:
            return np.bincount(y).argmax() if len(y) > 0 else 0

        best_gain = -1
        best_split = None

        for feat in range(X.shape[1]):
            for thr in np.unique(X[:, feat]):
                left_mask = X[:, feat] <= thr
                right_mask = ~left_mask
                if sum(left_mask) == 0 or sum(right_mask) == 0: continue

                # simple accuracy gain instead of entropy for speed
                p = np.zeros_like(y)
                p[left_mask] = np.bincount(y[left_mask]).argmax()
                p[right_mask] = np.bincount(y[right_mask]).argmax()
                gain = np.mean(p == y)

                if gain > best_gain:
                    best_gain = gain
                    best_split = (feat, thr, left_mask, right_mask)

        if best_split is None: return np.bincount(y).argmax()

        feat, thr, left_mask, right_mask = best_split
        return {
            'feat': feat,
            'thr': thr,
            'left': self._grow(X[left_mask], y[left_mask], depth+1),
            'right': self._grow(X[right_mask], y[right_mask], depth+1)
        }

    def predict(self, X):
        return np.array([self._pred(x, self.tree) for x in X])

    def _pred(self, x, node):
        if isinstance(node, (int, np.int64)): return node
        if x[node['feat']] <= node['thr']: return self._pred(x, node['left'])
        return self._pred(x, node['right'])

best_acc = 0
best_pair = None

for i in range(50):
    for j in range(i+1, 50):
        # 5 fold CV
        accs = []
        for k in range(5):
            val_idx = list(range(k*16, (k+1)*16))
            train_idx = [idx for idx in range(80) if idx not in val_idx]
            X_sub = X[:, [i, j]]
            model = DecisionTreeClassifier(max_depth=3)
            model.fit(X_sub[train_idx], y[train_idx])
            accs.append(np.mean(model.predict(X_sub[val_idx]) == y[val_idx]))

        acc = np.mean(accs)
        if acc > best_acc:
            best_acc = acc
            best_pair = (i, j)

print(f"Best pair tree: x{best_pair[0]+1:02d} and x{best_pair[1]+1:02d}, acc: {best_acc:.3f}")

